contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We accept an arbitrary amount to send to c.go
    function run(uint256 amount) public payable {
        require(address(this).balance >= amount, "insufficient balance to forward");

        // read owner and c balance before
        address ownerBefore = c.owner();
        uint256 cBalBefore = address(c).balance;
        uint256 myBalBefore = address(this).balance;

        // perform the call and record whether it reverted
        bool reverted;
        try c.go{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values
        address ownerAfter = c.owner();
        uint256 cBalAfter = address(c).balance;
        uint256 myBalAfter = address(this).balance;

        // General rule (single assert): if call reverted then c.balance is unchanged and owner unchanged;
        // otherwise (succeeded) owner unchanged, c holds zero, and this contract's balance did not increase.
        assert(
            (reverted && ownerAfter == ownerBefore && cBalAfter == cBalBefore)
            ||
            (!reverted && ownerAfter == ownerBefore && cBalAfter == 0 && myBalAfter <= myBalBefore)
        );
    }

    // Fallback/receive to allow c to send us ETH during the call (though rule expects it not to increase our balance on success)
    receive() external payable {}
}

contract InvMutTest {
    C c;
    address origOwner;
    constructor(C _c) { c = _c; origOwner = c.owner(); }
    function run(uint256 amount) public payable {
        require(address(this).balance >= amount);

        // record pre-call observable values
        address beforeOwner = c.owner();
        uint256 beforeCbal = address(c).balance;
        uint256 beforeThis = address(this).balance;

        bool reverted;
        // make the state-changing call as a top-level statement
        try c.go{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read post-call observables
        address afterOwner = c.owner();
        uint256 afterCbal = address(c).balance;
        uint256 afterThis = address(this).balance;

        // General rule:
        // 1) owner must never change
        // 2) If call succeeded (not reverted) then C's balance is zero (it forwards funds out)
        // 3) The test contract's balance cannot increase as a result of the call when it succeeded
        //    (any increase is only allowed when the call reverted, representing a refund)
        assert(
            afterOwner == beforeOwner
            && (
                reverted
                ? true
                : (afterCbal == 0 && afterThis <= beforeThis)
            )
        );
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    function run(uint256 amount) public payable {
        require(address(this).balance >= amount);

        // record owner and this-contract balance before the call
        address ownerBefore = c.owner();
        uint256 balanceBefore = address(this).balance;

        bool reverted;
        try c.go{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read owner and this-contract balance after the call
        address ownerAfter = c.owner();
        uint256 balanceAfter = address(this).balance;

        // General rule: either the call reverted, or owner unchanged and this contract's balance did not increase
        assert(reverted || (ownerAfter == ownerBefore && balanceAfter <= balanceBefore));
    }

    receive() external payable {}
}

