        // record balances before
        uint256 beforeThis = address(this).balance;
        uint256 beforeC = address(c).balance;
        address ownerBefore = c.owner();

        bool reverted;
        try c.go{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterThis = address(this).balance;
        uint256 afterC = address(c).balance;
        address ownerAfter = c.owner();

        // Assert single general property: either the call reverted, or if it succeeded
